def validate_uturn_footprint(station,half_length=2.8,half_width=1.25):
 # With centre (station+6sin(t),6cos(t)), heading -t, every corner has
 # y=(6+corner_y)cos(t)-corner_x sin(t). The analytic amplitude bounds all t.
