"""Strict retained-output validation. No simulator import and no legal judgment."""
import json,math,pathlib,hashlib
from worker_exchange.runtime_contract import validate_result,channel_samples,route_contained

def rows(path):
 with pathlib.Path(path).open() as f:return [json.loads(line) for line in f if line.strip()]

def contained(root,name):
 root=pathlib.Path(root).resolve();p=(root/name).resolve()
 if root not in p.parents or not p.is_file():raise ValueError('Missing contained evidence: '+str(name))
 return p

def validate_output(directory,result,requirements):
 root=pathlib.Path(directory);validate_result(root,result)
 trace=rows(contained(root,result['trace_reference']));mapping=rows(contained(root,result['video_frame_map_reference']))
 if not trace or len(trace)!=len(mapping):raise ValueError('Trace/video count mismatch')
 for i,(t,m) in enumerate(zip(trace,mapping)):
  if m.get('video_frame')!=i or m.get('carla_frame')!=t.get('frame') or m.get('time_s')!=t.get('time_s'):raise ValueError('Original frame/timestamp mismatch')
  if not isinstance(t.get('time_s'),(int,float)) or not math.isfinite(t['time_s']):raise ValueError('Invalid original timestamp')
  if i and t['time_s']<=trace[i-1]['time_s']:raise ValueError('Nonincreasing trace timestamps')
  if not all(k in t for k in ('position','heading_deg','speed_mps')):raise ValueError('Incomplete original telemetry')
 evidence={e['name']:e for e in result.get('recording_evidence',[])}
 for c in requirements['channels']:
  name=c['name']
  if name not in evidence:raise ValueError('Missing mandatory channel '+name)
  stream=rows(contained(root,evidence[name]['reference']));channel_samples(stream,len(trace))
  if any(s['time_s']!=t['time_s'] for s,t in zip(stream,trace)):raise ValueError('Channel timestamp mismatch '+name)
  dt=1/c['sampling_rate_hz']
  if any(abs(b['time_s']-a['time_s']-dt)>1e-5 for a,b in zip(stream,stream[1:])):raise ValueError('Channel rate mismatch '+name)
 for check in result['target_checks']:
  for key in ('target','requested','measured','method','tolerance','matched','physical_cause_confirmed','cause_evidence'):
   if key not in check:raise ValueError('Incomplete measured target '+key)
  if check['measured'] is None or check['matched'] is not True or check['physical_cause_confirmed'] is not True:raise ValueError('Unconfirmed measured target')
  if isinstance(check['measured'],float) and not math.isfinite(check['measured']):raise ValueError('Nonfinite measured target')
  if not check['method'] or not check['cause_evidence']:raise ValueError('Missing measurement provenance')
  refs=check['cause_evidence'] if isinstance(check['cause_evidence'],list) else [check['cause_evidence']]
  for ref in refs:contained(root,ref)
 for name in result['video_references']:
  video=contained(root,name)
  with video.open('rb') as f:header=f.read(64)
  if b'ftyp' not in header and not header.startswith(bytes.fromhex('1a45dfa3')):raise ValueError('Encoded video container required; PNG paths are invalid')
  inspect_video(video,len(trace))
 for name,definition in result.get('realized_observables',{}).items():
  raw=rows(contained(root,definition['reference']));window=definition.get('sample_window_s')
  if not window or len(window)!=2:raise ValueError('Missing actual summary sample window')
  data=[s['value'] for s in raw if window[0]<=s['time_s']<=window[1]]
  if not data:raise ValueError('Empty summary window')
  stat=definition['statistic'];actual=sum(data)/len(data) if stat=='mean' else min(data) if stat=='min' else max(data) if stat=='max' else None
  if actual is None or not math.isclose(actual,definition['value'],rel_tol=1e-9,abs_tol=1e-9):raise ValueError('Summary not recomputable from original samples')
 for context in requirements.get('context_inputs',[]):
  name=context['name']
  if name not in evidence:raise ValueError('Missing authored context '+name)
  value=json.loads(contained(root,evidence[name]['reference']).read_text())
  if name not in value or value[name] is None:raise ValueError('Unavailable authored context '+name)
 if result.get('required_participant_ids'):
  history=rows(contained(root,result['participant_history_reference']))
  if len(history)!=len(trace):raise ValueError('Incomplete participant history')
  required=set(result['required_participant_ids'])
  for h,t in zip(history,trace):
   if h['time_s']!=t['time_s'] or not required<={p['actor_id'] for p in h['participants']}:raise ValueError('Missing required participant in original frame')
 if result.get('footprint_reference'):
  history=rows(contained(root,result['footprint_reference']));polygons=result['driving_polygons']
  if len(history)!=len(trace):raise ValueError('Incomplete footprint history')
  for sample in history:
   for vertex in sample['vertices']:
    if not any(_inside(vertex[:2],polygon) for polygon in polygons):raise ValueError('Route/body footprint outside authored surface')
 return True

def _inside(vertex,polygon):
 try:route_contained([vertex],polygon);return True
 except ValueError:return False

def measured_target(name,requested,measured,tolerance,method,evidence,physical=True):
 if isinstance(requested,(int,float)) and not isinstance(requested,bool):matched=measured is not None and abs(measured-requested)<=tolerance
 else:matched=measured==requested
 return dict(target=name,requested=requested,measured=measured,tolerance=tolerance,method=method,matched=bool(matched),physical_cause_confirmed=bool(physical),cause_evidence=evidence)

def summarize(samples,start,end,statistic='mean'):
 selected=[s for s in samples if start<=s['time_s']<=end]
 if not selected:raise ValueError('No actual samples in declared window')
 values=[s['value'] for s in selected]
 if any(v is None for v in values):raise ValueError('Missing actual measurement')
 value=sum(values)/len(values) if statistic=='mean' else min(values) if statistic=='min' else max(values) if statistic=='max' else None
 if value is None:raise ValueError('Unsupported statistic')
 return value,[selected[0]['time_s'],selected[-1]['time_s']]

def inspect_video(path,expected_frames,hz=20):
 import subprocess
 p=subprocess.run(['ffprobe','-v','error','-count_frames','-show_entries','stream=nb_read_frames,avg_frame_rate','-of','json',str(path)],stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True)
 if p.returncode:raise ValueError('Encoded video cannot be decoded')
 streams=json.loads(p.stdout).get('streams',[])
 if not streams or int(streams[0].get('nb_read_frames',-1))!=expected_frames:raise ValueError('Encoded video/trace frame count mismatch')
 numerator,denominator=map(float,streams[0]['avg_frame_rate'].split('/'))
 if not denominator or abs(numerator/denominator-hz)>1e-6:raise ValueError('Encoded video rate mismatch')
 return True

"""Original-tick RGB encoding and mandatory measured channel capture."""
import json,pathlib,queue,subprocess,sys

class Resources:
 def __init__(self):self.callbacks=[]
 def own(self,callback):self.callbacks.append(callback)
 def close(self):
  errors=[]
  for callback in reversed(self.callbacks):
   try:callback()
   except BaseException as e:errors.append(type(e).__name__+': '+str(e))
  self.callbacks=[];return errors

class Recording:
 def __init__(self,client,ego,output,case_id,description,cameras,required_atoms=()):
  self.output=pathlib.Path(output);self.output.mkdir(parents=True,exist_ok=True);self.resources=Resources();self.channels={};self.evidence=[];self.cameras=[];self.encoders=[];self.frames=0;self.closed=False;self.close_errors=[]
  self.description=description
  try:
   import carla
   from pipeline_capture import PipelineCapture
   self.capture=PipelineCapture(client,ego,self.output,case_id,required_observations=required_atoms);self.resources.own(lambda:self.capture.close(confirmed=not self.close_errors))
   self.evidence_reader=(self.output/'capture/evidence.jsonl').open();self.resources.own(self.evidence_reader.close);self.last_evidence=None
   for idx,pose in enumerate(cameras):
    bp=client.get_world().get_blueprint_library().find('sensor.camera.rgb');width=pose.get('width',1920 if idx==0 else 1280);height=pose.get('height',1080 if idx==0 else 720)
    bp.set_attribute('image_size_x',str(width));bp.set_attribute('image_size_y',str(height));bp.set_attribute('sensor_tick','0.0')
    loc=pose.get('location',[pose.get('x',-8),pose.get('y',0),pose.get('z',4)])
    camera=client.get_world().spawn_actor(bp,carla.Transform(carla.Location(*loc),carla.Rotation(pitch=pose.get('pitch',-15))),attach_to=ego)
    self.resources.own(camera.destroy);self.resources.own(camera.stop);q=queue.Queue();camera.listen(q.put);self.cameras.append(q)
    path=self.output/('camera-'+str(idx)+'.webm')
    process=subprocess.Popen(['ffmpeg','-v','error','-n','-f','rawvideo','-pixel_format','bgra','-video_size',str(width)+'x'+str(height),'-framerate','20','-i','pipe:0','-an','-c:v','libvpx-vp9','-deadline','realtime','-cpu-used','8','-pix_fmt','yuv420p',str(path)],stdin=subprocess.PIPE,stderr=subprocess.PIPE)
    self.encoders.append(process);self.resources.own(lambda p=process:self._finish_encoder(p))
   self.frame_map=(self.output/'video_frame_map.jsonl').open('x');self.resources.own(self.frame_map.close)
   (self.output/'channels').mkdir(exist_ok=False)
   for c in description['channels']:
    name=c['name'];p=self.output/'channels'/(name+'.jsonl');f=p.open('x');self.channels[name]=f;self.resources.own(f.close);self.evidence.append(dict(name=name,unit=c['unit'],reference='channels/'+name+'.jsonl'))
  except BaseException:self.close();raise
 def _finish_encoder(self,process):
  if process.stdin and not process.stdin.closed:process.stdin.close()
  error=process.stderr.read();code=process.wait(timeout=90)
  if code:raise RuntimeError('Video encoder failed: '+error.decode(errors='replace'))
 def tick(self,frame,time_s,observations,extra=None):
  row=self.capture.capture(frame,time_s,extra=extra)
  event=self.evidence_reader.readline()
  if not event:raise RuntimeError('Missing original captured observation packet')
  self.last_evidence=json.loads(event)
  if self.last_evidence['original_frame']!=frame:raise RuntimeError('Original evidence frame mismatch')
  if callable(observations):observations=observations(row,self.last_evidence)
  missing=[name for name in self.channels if observations.get(name) is None]
  if missing:raise ValueError('Mandatory observation unavailable: '+','.join(missing))
  for name,f in self.channels.items():f.write(json.dumps(dict(time_s=time_s,value=observations[name]))+'\n')
  for q,encoder in zip(self.cameras,self.encoders):
   image=q.get(timeout=30)
   while image.frame<frame:image=q.get(timeout=30)
   if image.frame!=frame:raise RuntimeError('Original camera timestamp mismatch')
   encoder.stdin.write(bytes(image.raw_data))
  self.frame_map.write(json.dumps(dict(video_frame=self.frames,carla_frame=frame,time_s=time_s))+'\n');self.frames+=1
  return row
 def close(self):
  if not self.closed:self.closed=True;self.close_errors+=self.resources.close()
  return self.close_errors
 def result_fields(self):
  return dict(trace_reference='trace.jsonl',video_frame_map_reference='video_frame_map.jsonl',video_references=['camera-'+str(i)+'.webm' for i in range(len(self.cameras))],recording_evidence=self.evidence,recording_description=self.description)

"""Small, standard-library-only file and identity helpers."""
import hashlib
import json
import os
import re
import tempfile
from pathlib import Path, PurePosixPath

SETS = ('demo-train', 'demo-test', 'held-out', 'full-train', 'full-test')
SKILLS = ('law-grounded-cells', 'law-relevance-mapping', 'law-cell-bindings',
          'law-judgment-observables', 'scenario-coverage-cases', 'carla-scenario-build')


def read(path):
    return json.loads(Path(path).read_text())


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':'),
                                     ensure_ascii=False).encode()).hexdigest()


def sha(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def write(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=path.parent, prefix='.' + path.name)
    try:
        with os.fdopen(fd, 'w') as stream:
            stream.write(json.dumps(value, indent=2, ensure_ascii=False) + '\n')
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(tmp, path)
    finally:
        if Path(tmp).exists():
            Path(tmp).unlink()


def name(value):
    if not isinstance(value, str) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]*', value):
        raise ValueError('Unsafe identifier: ' + str(value))
    return value


def within(root, relative):
    raw = PurePosixPath(str(relative))
    if raw.is_absolute() or not raw.parts or any(p in ('..', '.') for p in raw.parts) or '\\' in str(relative):
        raise ValueError('Expected a relative contained path: ' + str(relative))
    root = Path(root).resolve()
    path = root.joinpath(*raw.parts)
    # A symlink into the tree is also forbidden: portable packages carry files.
    for parent in [path, *path.parents]:
        if parent == root:
            break
        if parent.is_symlink():
            raise ValueError('Symlink in package: ' + str(relative))
    if root not in path.resolve().parents:
        raise ValueError('Path escapes root: ' + str(relative))
    return path


def assignment_id(a, role):
    # Demo/full overlap must not create a second implementation.
    return '__'.join(name(str(x)) for x in (role, a['cell_id'], a['law_id'], a['actor']))


def tree(root):
    result = {}
    for path in sorted(Path(root).rglob('*')):
        rel = path.relative_to(root)
        if any(p in ('.git', '__pycache__', '.pytest_cache') for p in rel.parts) or path.suffix == '.pyc':
            continue
        within(root, rel.as_posix())
        if path.is_file():
            result[rel.as_posix()] = sha(path)
    return result

"""Portable result/geometry checks. Used by CPU fixtures and live finalization."""
import math
from pathlib import Path
from .common import read


def validate_result(directory, result):
    directory=Path(directory)
    for key in ('setup_confirmed','behavior_attempted','maneuver_completed'):
        if result.get(key) is not True:raise ValueError('Incomplete '+key)
    if result.get('physical_failure_flags'):raise ValueError('Physical/capture failures remain')
    videos=result.get('video_references')
    if not videos or any(not isinstance(v,str) for v in videos):raise ValueError('Encoded video file paths required')
    for name in videos:
        path=(directory/name).resolve()
        if directory.resolve() not in path.parents or not path.is_file():raise ValueError('Missing contained video')
    for key in ('trace_reference','video_frame_map_reference'):
        if not isinstance(result.get(key),str) or not (directory/result[key]).is_file():raise ValueError('Missing '+key)
    if not result.get('target_checks'):raise ValueError('Missing measured target checks')
    return True


def channel_samples(samples, expected_frames):
    if len(samples)!=expected_frames:raise ValueError('Incomplete channel history')
    for sample in samples:
        if sample.get('value') is None or sample.get('missing_capability'):raise ValueError('Unimplemented mandatory channel')
        if not isinstance(sample.get('time_s'),(int,float)) or not math.isfinite(sample['time_s']):raise ValueError('Invalid time')
    if any(a['time_s']>=b['time_s'] for a,b in zip(samples,samples[1:])):raise ValueError('Nonincreasing times')
    return True


def route_contained(vertices, polygon):
    """All supplied footprint vertices must lie in the authored reference polygon."""
    def inside(p):
        x,y=p;odd=False
        for a,b in zip(polygon,polygon[1:]+polygon[:1]):
            cross=(x-a[0])*(b[1]-a[1])-(y-a[1])*(b[0]-a[0])
            if abs(cross)<1e-9 and min(a[0],b[0])<=x<=max(a[0],b[0]) and min(a[1],b[1])<=y<=max(a[1],b[1]):return True
            if (a[1]>y)!=(b[1]>y) and x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]:odd=not odd
        return odd
    if not polygon or not vertices or not all(inside(v) for v in vertices):raise ValueError('Footprint outside reference region')
    return True

